-- Only promote untouched non-art drafts. Art records and editor changes are protected.
begin;
create temporary table kk_art_changed(id uuid primary key) on commit drop;
with changed as (
 insert into public.kk_museums as m(id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum)
 select id,inventory_key,name,city,province,street_address,postal_code,country,website_url,latitude,longitude,summary,operating_status,publication_status,verification_status,tags,photos,is_art_museum from jsonb_populate_recordset(null::public.kk_museums,'[{"id":"0376541b-4d5f-5b8b-853a-007e6ae3920d","inventory_key":"museum-nl:hart-museum","name":"H''ART Museum","city":"Amsterdam","province":"Noord-Holland","street_address":"51 Amstel","postal_code":"1018 EJ","country":"NL","website_url":"https://www.hartmuseum.nl/en/","latitude":52.364814,"longitude":4.902185,"summary":"Reis door de kunst met wisselende tentoonstellingen in een historisch gebouw aan de Amstel. H’ART brengt internationale kunstcollecties naar Amsterdam: telkens een andere ontmoeting met kunstenaars, tijdperken en verhalen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunsthal","oude kunst","moderne kunst","hedendaagse kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Amsterdam_-_Amstel_-_View_on_river_Amstel_%26_Museum_Hermitage_Amsterdam.jpg/1280px-Amsterdam_-_Amstel_-_View_on_river_Amstel_%26_Museum_Hermitage_Amsterdam.jpg","caption":"H''ART Museum — Amsterdam - Amstel - View on river Amstel & Museum Hermitage Amsterdam","credit":"Txllxt TxllxT","source_url":"https://commons.wikimedia.org/wiki/File:Amsterdam_-_Amstel_-_View_on_river_Amstel_%26_Museum_Hermitage_Amsterdam.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"51f162b9-5df8-58d9-b7c3-30d0eb7ac3f6","inventory_key":"museum-nl:museum-panorama-mesdag","name":"Museum Panorama Mesdag","city":"Den Haag","province":"Zuid-Holland","street_address":"Zeestraat 65","postal_code":"2518 AA","country":"NL","website_url":"https://www.panorama-mesdag.nl/","latitude":52.084794,"longitude":4.303302,"summary":"Laat je omringen door het Scheveningen van Mesdag. Het grote panorama maakt zee, duin en dorp tot een ruimtelijke ervaring. Schilderijen van Hendrik Willem Mesdag en Sientje Mesdag-van Houten verdiepen de kennismaking met hun kunstenaarschap.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","Haagse School","panorama"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Overzicht_voorgevel_in_straatbeeld_20411247_RCE.jpg/1280px-Overzicht_voorgevel_in_straatbeeld_20411247_RCE.jpg","caption":"Museum Panorama Mesdag — Overzicht voorgevel in straatbeeld 20411247 RCE","credit":"Sergé Technau","source_url":"https://commons.wikimedia.org/wiki/File:Overzicht_voorgevel_in_straatbeeld_20411247_RCE.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"5402debd-2567-5c85-af4d-31354fd1f113","inventory_key":"museum-nl:museum-boijmans-van-beuningen","name":"Museum Boijmans Van Beuningen","city":"Rotterdam","province":"Zuid-Holland","street_address":"Museumpark 18-20","postal_code":"3015 CX","country":"NL","website_url":"https://www.boijmans.nl/","latitude":51.91442,"longitude":4.473268,"summary":"Van oude meesters tot eigentijds design: de verzameling van Boijmans verbindt eeuwen kunst. Het museumgebouw wordt gerenoveerd. In het afzonderlijk te bezoeken Depot ontdek je intussen hoe deze veelzijdige collectie wordt bewaard.","operating_status":"temporarily_closed","publication_status":"draft","verification_status":"unreviewed","tags":["oude kunst","moderne kunst","design","schilderkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/Museumpark_02.JPG/1280px-Museumpark_02.JPG","caption":"Museum Boijmans Van Beuningen — Museumpark 02","credit":"K. Siereveld","source_url":"https://commons.wikimedia.org/wiki/File:Museumpark_02.JPG","license":"Public domain"}],"is_art_museum":true},{"id":"d908d0df-29a8-5c7e-a1a1-2be836132fab","inventory_key":"museum-nl:teylers-museum","name":"Teylers Museum","city":"Haarlem","province":"Noord-Holland","street_address":"Spaarne 16","postal_code":"2011 CH","country":"NL","website_url":"https://www.teylersmuseum.nl/nl","latitude":52.380345,"longitude":4.64035,"summary":"Neem de tijd voor tekeningen, prenten en schilderijen in de historische zalen van Teylers. Oude meesters, romantische landschappen en de Haagse School delen hier hun huis met wetenschappelijke instrumenten en natuurhistorische schatten.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["tekenkunst","schilderkunst","oude kunst","Haagse School"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/TeylersHaarlem2.JPG/1280px-TeylersHaarlem2.JPG","caption":"Teylers Museum — TeylersHaarlem2","credit":"Vysotsky","source_url":"https://commons.wikimedia.org/wiki/File:TeylersHaarlem2.JPG","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"e6b6688b-3189-5792-ba31-cbc8cb245510","inventory_key":"wikipedia:Zuid-Holland:kijkkubus:rotterdam","name":"Kijk-kubus","city":"Rotterdam","province":"Zuid-Holland","street_address":"Overblaak 70","postal_code":"3011 MH","country":"NL","website_url":"https://kubuswoning.nl/","latitude":null,"longitude":null,"summary":"Hoe woon je in een gekantelde kubus? Stap binnen in een museumwoning van Piet Blom en ontdek hoe schuine wanden, licht en inventieve indelingen samen een verrassend woonontwerp vormen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["architectuur","design","museumwoning"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Rotterdam_kubuswoningen.jpg/1280px-Rotterdam_kubuswoningen.jpg","caption":"Kijk-kubus — Rotterdam kubuswoningen","credit":"F. Eveleens","source_url":"https://commons.wikimedia.org/wiki/File:Rotterdam_kubuswoningen.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"cd78184c-a1ee-5884-870b-093e0a2120ef","inventory_key":"museum-nl:drents-museum","name":"Drents Museum","city":"Assen","province":"Drenthe","street_address":"Brink 1","postal_code":"9401 HS","country":"NL","website_url":"https://drentsmuseum.nl/","latitude":52.992901,"longitude":6.564276,"summary":"Ontdek hedendaags realisme en kunst rond 1900 in het Drents Museum. Schilderkunst en kunstnijverheid vormen er een belangrijk zwaartepunt naast archeologie. Wisselende tentoonstellingen verbinden de verzameling met nieuwe kunstenaars en perspectieven.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["realisme","moderne kunst","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/2005_Assen_Museum_Drenthe_01.JPG/1280px-2005_Assen_Museum_Drenthe_01.JPG","caption":"Drents Museum — 2005 Assen Museum Drenthe 01","credit":"Ziko","source_url":"https://commons.wikimedia.org/wiki/File:2005_Assen_Museum_Drenthe_01.JPG","license":"CC BY-SA 3.0 nl"}],"is_art_museum":true},{"id":"ed3f9408-8d30-53d9-92fd-30c1c3cb633a","inventory_key":"wikipedia:Utrecht:rietveldschroderhuis:utrecht","name":"Rietveld Schröderhuis","city":"Utrecht","province":"Utrecht","street_address":"Prins Hendriklaan 50","postal_code":"3583 EP","country":"NL","website_url":"https://centraalmuseum.nl/bezoeken/locaties/rietveld-schroederhuis/","latitude":null,"longitude":null,"summary":"Ontdek hoe Gerrit Rietveld en Truus Schröder ruimte opnieuw uitvonden. Kleuren, verschuifbare wanden en slimme meubels maken van dit huis een levend experiment van De Stijl. Het interieur is hier zelf het kunstwerk.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["architectuur","De Stijl","design","museumwoning"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Rietveld_Schr%C3%B6derhuis_HayKranen-7.JPG/1280px-Rietveld_Schr%C3%B6derhuis_HayKranen-7.JPG","caption":"Rietveld Schröderhuis — Rietveld Schröderhuis HayKranen-7","credit":"User:Husky","source_url":"https://commons.wikimedia.org/wiki/File:Rietveld_Schr%C3%B6derhuis_HayKranen-7.JPG","license":"CC BY 3.0"}],"is_art_museum":true},{"id":"aa92a112-916f-54a7-8bce-bdb310a39db0","inventory_key":"wikipedia:Zuid-Holland:vermeercentrum:delft","name":"Vermeer Centrum Delft","city":"Delft","province":"Zuid-Holland","street_address":"Voldersgracht 21","postal_code":"2611 EV","country":"NL","website_url":"https://www.vermeerdelft.nl/nl/","latitude":null,"longitude":null,"summary":"Duik in de wereld van Johannes Vermeer: zijn licht, zijn atelier en zijn Delft. Reproducties maken zijn oeuvre samen zichtbaar en helpen je details ontdekken. Je bezoekt hier een interpretatiecentrum, geen verzameling originele Vermeers.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["oude meesters","schilderkunst","kunstenaarsmuseum"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/Het_Vermeer_Centrum_in_Delft_aan_de_Voldersgracht_%282021%29.jpg/1280px-Het_Vermeer_Centrum_in_Delft_aan_de_Voldersgracht_%282021%29.jpg","caption":"Vermeer Centrum Delft — Het Vermeer Centrum in Delft aan de Voldersgracht (2021)","credit":"MatteoNL97","source_url":"https://commons.wikimedia.org/wiki/File:Het_Vermeer_Centrum_in_Delft_aan_de_Voldersgracht_(2021).jpg","license":"CC BY 4.0"}],"is_art_museum":true},{"id":"cc66ef0a-4e1d-5376-9f63-0d65a78676fd","inventory_key":"museum-nl:kunsthal-rotterdam","name":"Kunsthal Rotterdam","city":"Rotterdam","province":"Zuid-Holland","street_address":"Westzeedijk 341","postal_code":"3015 AA","country":"NL","website_url":"https://www.kunsthal.nl/nl/","latitude":51.910673,"longitude":4.473386,"summary":"Laat je verrassen door kunst, fotografie en cultuur uit uiteenlopende werelden. De Kunsthal heeft geen vaste collectie: wisselende tentoonstellingen geven telkens een andere invulling aan het uitgesproken gebouw van Rem Koolhaas.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunsthal","hedendaagse kunst","moderne kunst","fotografie"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/74/Kunsthal_Rotterdam.JPG/1280px-Kunsthal_Rotterdam.JPG","caption":"Kunsthal Rotterdam — Kunsthal Rotterdam","credit":"Jeffrey Beall","source_url":"https://commons.wikimedia.org/wiki/File:Kunsthal_Rotterdam.JPG","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"f5b4eb15-d3db-506b-8356-724de9e15d1b","inventory_key":"museum-nl:eye-filmmuseum","name":"EYE","city":"Amsterdam","province":"Noord-Holland","street_address":"IJpromenade 1","postal_code":"1031 KT","country":"NL","website_url":"https://www.eyefilm.nl/","latitude":52.384136,"longitude":4.901294,"summary":"Kijk verder dan het bioscoopscherm. Eye verkent film als kunstvorm, met tentoonstellingen waarin bewegend beeld, makers en experiment centraal staan. De omvangrijke filmverzameling vormt de achtergrond van een veelzijdig programma.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["film","videokunst","bewegend beeld"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/EYE_Filmmuseum.jpg/1280px-EYE_Filmmuseum.jpg","caption":"EYE — EYE Filmmuseum","credit":"Jvhertum","source_url":"https://commons.wikimedia.org/wiki/File:EYE_Filmmuseum.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"c3bd7029-8733-5619-8525-3a538efda7dd","inventory_key":"art-audit:23","name":"Fabrique des Lumières","city":"Amsterdam","province":"Noord-Holland","street_address":"37 Pazzanistraat","postal_code":"1014 DB","country":"NL","website_url":"https://www.fabrique-lumieres.com/","latitude":null,"longitude":null,"summary":"Zie schilderkunst veranderen in een omgeving van licht, beweging en muziek. Fabrique des Lumières presenteert wisselende digitale bewerkingen van kunstwerken in een voormalige gasfabriek. Je beleeft projecties; de originele schilderijen hangen elders.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["digitale kunst","immersieve kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Overzicht_gevel_langs_de_Haarlemmervaart_van_het_zuiveringsgebouw_van_de_Westergasfabriek_-_Amsterdam_-_20409032_-_RCE.jpg/1280px-Overzicht_gevel_langs_de_Haarlemmervaart_van_het_zuiveringsgebouw_van_de_Westergasfabriek_-_Amsterdam_-_20409032_-_RCE.jpg","caption":"Fabrique des Lumières — Overzicht gevel langs de Haarlemmervaart van het zuiveringsgebouw van de Westergasfabriek - Amsterdam - 20409032 - RCE","credit":"Sergé Technau","source_url":"https://commons.wikimedia.org/wiki/File:Overzicht_gevel_langs_de_Haarlemmervaart_van_het_zuiveringsgebouw_van_de_Westergasfabriek_-_Amsterdam_-_20409032_-_RCE.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"b8aacf17-b869-50b4-a72c-805da2ea4054","inventory_key":"museum-nl:museum-de-fundatie","name":"Museum de Fundatie","city":"Zwolle","province":"Overijssel","street_address":"Blijmarkt 20","postal_code":"8011 NE","country":"NL","website_url":"https://www.museumdefundatie.nl/","latitude":52.510239,"longitude":6.091502,"summary":"Ontdek beeldende kunst vanuit de veelzijdige verzameling van Museum de Fundatie. Schilderijen en sculpturen uit verschillende perioden krijgen nieuwe verbanden in wisselende tentoonstellingen. Het voormalige Paleis van Justitie vormt een markant decor.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["moderne kunst","schilderkunst","hedendaagse kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/20150819_Museum_de_Fundatie_Zwolle.jpg/1280px-20150819_Museum_de_Fundatie_Zwolle.jpg","caption":"Museum de Fundatie — 20150819 Museum de Fundatie Zwolle","credit":"Gouwenaar","source_url":"https://commons.wikimedia.org/wiki/File:20150819_Museum_de_Fundatie_Zwolle.jpg","license":"CC0"}],"is_art_museum":true},{"id":"087b3436-17a7-5267-a11c-b5bcc00e8dfc","inventory_key":"museum-nl:museum-prinsenhof-delft","name":"Museum Prinsenhof Delft","city":"Delft","province":"Zuid-Holland","street_address":"Sint Agathaplein 1","postal_code":"2611 HR","country":"NL","website_url":"https://prinsenhof-delft.nl/","latitude":52.012144,"longitude":4.354486,"summary":"Delftse schilderkunst, Delfts blauw en het verhaal van Willem van Oranje ontmoeten elkaar in het Prinsenhof. Het museum is tijdelijk gesloten voor vernieuwing; delen van de collectie en activiteiten zijn op andere locaties te vinden.","operating_status":"temporarily_closed","publication_status":"draft","verification_status":"unreviewed","tags":["oude kunst","keramiek","Delfts blauw"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Delft_-_Prinsenhof_in_the_Netherlands.jpg/1280px-Delft_-_Prinsenhof_in_the_Netherlands.jpg","caption":"Museum Prinsenhof Delft — Delft - Prinsenhof in the Netherlands","credit":"Malis","source_url":"https://commons.wikimedia.org/wiki/File:Delft_-_Prinsenhof_in_the_Netherlands.jpg","license":"Public domain"}],"is_art_museum":true},{"id":"ff63aeea-705e-54d2-8239-77a240672090","inventory_key":"wikipedia:Noord-Brabant:jheronimusboschartcenter:denbosch","name":"Jheronimus Bosch Art Center","city":"''s-Hertogenbosch","province":"Noord-Brabant","street_address":"Jeroen Boschplein 2","postal_code":"5211 ML","country":"NL","website_url":"https://www.jheronimusbosch-artcenter.nl/","latitude":null,"longitude":null,"summary":"Verdwaal in de wonderlijke beeldtaal van Jheronimus Bosch. Reproducties van zijn schilderijen brengen monsters, symbolen en kleine verhalen dichtbij. Dit kunstcentrum biedt een kennismaking met zijn oeuvre, zonder originele schilderijen te claimen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["oude meesters","kunstenaarsmuseum","schilderkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Sculptuur-fontein_%27Jheronimus_Bosch_Art_Centre%27_%282007%29_door_Ruudt_Peters%2C_Jeroen_Boschplein_2%2C_%27s-Hertogenbosch_01.jpg/1280px-Sculptuur-fontein_%27Jheronimus_Bosch_Art_Centre%27_%282007%29_door_Ruudt_Peters%2C_Jeroen_Boschplein_2%2C_%27s-Hertogenbosch_01.jpg","caption":"Jheronimus Bosch Art Center — Sculptuur-fontein ''Jheronimus Bosch Art Centre'' (2007) door Ruudt Peters, Jeroen Boschplein 2, ''s-Hertogenbosch 01","credit":"FakirNL","source_url":"https://commons.wikimedia.org/wiki/File:Sculptuur-fontein_%27Jheronimus_Bosch_Art_Centre%27_(2007)_door_Ruudt_Peters,_Jeroen_Boschplein_2,_%27s-Hertogenbosch_01.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"bc076b1b-963a-5ab5-8429-fea490835ac5","inventory_key":"wikipedia:Zuid-Holland:escherinhetpaleis:denhaag","name":"Escher in Het  Paleis","city":"Den Haag","province":"Zuid-Holland","street_address":"Lange Voorhout 74","postal_code":"2514 EH","country":"NL","website_url":"https://www.escherinhetpaleis.nl/","latitude":null,"longitude":null,"summary":"Trappen die eindeloos doorgaan, vogels die veranderen in vissen: Eschers prenten blijven je ogen uitdagen. Ontdek hoe nauwkeurig tekenen en speelse verbeelding samen onmogelijke werelden voortbrengen in een voormalig paleis.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["grafiek","kunstenaarsmuseum","optische illusies"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Escher_Paleis_-_Den_Haag_%288168707204%29.jpg/1280px-Escher_Paleis_-_Den_Haag_%288168707204%29.jpg","caption":"Escher in Het  Paleis — Escher Paleis - Den Haag (8168707204)","credit":"Ferdi De gier from The Hague, Netherlands","source_url":"https://commons.wikimedia.org/wiki/File:Escher_Paleis_-_Den_Haag_(8168707204).jpg","license":"CC BY-SA 2.0"}],"is_art_museum":true},{"id":"ba68d5d3-b373-54ff-b353-d23b8c4b9928","inventory_key":"museum-nl:huis-willet-holthuysen","name":"Huis Willet-Holthuysen","city":"Amsterdam","province":"Noord-Holland","street_address":"Herengracht 605","postal_code":"1017 CE","country":"NL","website_url":"https://www.willetholthuysen.nl/","latitude":52.365603,"longitude":4.899015,"summary":"Ontdek de smaak van negentiende-eeuwse verzamelaars in een rijk ingericht grachtenhuis. Kunstvoorwerpen, meubelen en historische interieurs vertellen samen hoe kunst een plek kreeg in het dagelijks leven van het echtpaar Willet-Holthuysen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["toegepaste kunst","oude kunst","verzamelaars"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Willet-holthuysen2.jpg/1280px-Willet-holthuysen2.jpg","caption":"Huis Willet-Holthuysen — Willet-holthuysen2","credit":"Jvhertum","source_url":"https://commons.wikimedia.org/wiki/File:Willet-holthuysen2.jpg","license":"Public domain"}],"is_art_museum":true},{"id":"ecb8adbb-a48b-51e4-8a84-386a04106acf","inventory_key":"museum-nl:het-noordbrabants-museum","name":"Het Noordbrabants Museum","city":"''s-Hertogenbosch","province":"Noord-Brabant","street_address":"Verwersstraat 41","postal_code":"5211 HT","country":"NL","website_url":"https://www.hetnoordbrabantsmuseum.nl/","latitude":51.68658,"longitude":5.304685,"summary":"Ontmoet Brabant door de ogen van kunstenaars. Het Noordbrabants Museum combineert schilderkunst en kunstnijverheid met geschiedenis, en geeft in wisselende tentoonstellingen ruimte aan nieuwe blikken op de streek en de wereld daarbuiten.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","oude kunst","moderne kunst","Brabant"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/Brabants_Museum_main_entrance_building_Den_Bosch_at_21_May_2015_-_panoramio.jpg/1280px-Brabants_Museum_main_entrance_building_Den_Bosch_at_21_May_2015_-_panoramio.jpg","caption":"Het Noordbrabants Museum — Brabants Museum main entrance building Den Bosch at 21 May 2015 - panoramio","credit":"Henk Monster","source_url":"https://commons.wikimedia.org/wiki/File:Brabants_Museum_main_entrance_building_Den_Bosch_at_21_May_2015_-_panoramio.jpg","license":"CC BY 3.0"}],"is_art_museum":true},{"id":"14e73814-2d29-5368-be44-2252dc1fcf6d","inventory_key":"museum-nl:de-mesdag-collectie","name":"De Mesdag Collectie","city":"Den Haag","province":"Zuid-Holland","street_address":"Laan van Meerdervoort 7F","postal_code":"2517 AB","country":"NL","website_url":"https://www.demesdagcollectie.nl/","latitude":52.08599,"longitude":4.298126,"summary":"Kijk mee met Hendrik Willem en Sientje Mesdag, kunstenaars én verzamelaars. Hun collectie brengt de Haagse School en de School van Barbizon samen. Landschappen, licht en vrij geschilderde natuur maken dit een intieme ontdekkingstocht.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["Haagse School","School van Barbizon","schilderkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/Barberini_August_2023-Anton_Mauve_-_In_Scheveningen%2C1876_-_De_Mesdag_Collectie%2C_Den_Haag_%28cropped%29.jpg/1280px-Barberini_August_2023-Anton_Mauve_-_In_Scheveningen%2C1876_-_De_Mesdag_Collectie%2C_Den_Haag_%28cropped%29.jpg","caption":"De Mesdag Collectie — Barberini August 2023-Anton Mauve - In Scheveningen,1876 - De Mesdag Collectie, Den Haag (cropped)","credit":"Anton Mauve","source_url":"https://commons.wikimedia.org/wiki/File:Barberini_August_2023-Anton_Mauve_-_In_Scheveningen,1876_-_De_Mesdag_Collectie,_Den_Haag_(cropped).jpg","license":"Public domain"}],"is_art_museum":true},{"id":"8e5547e7-285e-580a-8424-b560c801de22","inventory_key":"museum-nl:van-gogh-etten-leur-museum-sint-paulushofje","name":"Van Gogh Kerk Etten-Leur","city":"Etten-Leur","province":"Noord-Brabant","street_address":"Markt 4","postal_code":"4875 CE","country":"NL","website_url":"https://www.vangoghbrabant.com/nl/home/etten-leur","latitude":51.57124,"longitude":4.633843,"summary":"Ontdek het begin van Van Goghs kunstenaarschap in Etten-Leur. Het verhaal van zijn tijd hier brengt zijn zoektocht als tekenaar tot leven. De presentatie draait om zijn ontwikkeling en omgeving, niet om een vaste collectie originele schilderijen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunstenaarsmuseum","Vincent van Gogh"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Etten-Leur_Kerk.jpg/1280px-Etten-Leur_Kerk.jpg","caption":"Van Gogh Kerk Etten-Leur — Etten-Leur Kerk","credit":"Yhoitink","source_url":"https://commons.wikimedia.org/wiki/File:Etten-Leur_Kerk.jpg","license":"CC BY-SA 3.0 nl"}],"is_art_museum":true},{"id":"abe177c0-7a81-528f-84af-ceca3adf4275","inventory_key":"museum-nl:museum-catharijneconvent","name":"Museum Catharijneconvent","city":"Utrecht","province":"Utrecht","street_address":"Lange Nieuwstraat 38","postal_code":"3512 PH","country":"NL","website_url":"https://www.catharijneconvent.nl/","latitude":52.087289,"longitude":5.123924,"summary":"Eeuwen geloof hebben bijzondere kunst voortgebracht. Ontdek schilderijen, middeleeuwse beelden, kostbaar edelsmeedwerk en manuscripten in het Catharijneconvent. Oude en eigentijdse werken laten zien hoe kunstenaars betekenis geven aan grote levensvragen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["religieuze kunst","oude kunst","beeldhouwkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Catharijneconvent.JPG/1280px-Catharijneconvent.JPG","caption":"Museum Catharijneconvent — Catharijneconvent","credit":"Luctor IV","source_url":"https://commons.wikimedia.org/wiki/File:Catharijneconvent.JPG","license":"CC BY-SA 3.0"}],"is_art_museum":true},{"id":"3141bb58-2bee-5b3c-ae96-c7f4a16886e9","inventory_key":"museum-nl:nederlands-fotomuseum","name":"Nederlands Fotomuseum","city":"Rotterdam","province":"Zuid-Holland","street_address":"Brede Hilledijk 95","postal_code":"3072 KD","country":"NL","website_url":"https://nederlandsfotomuseum.nl/","latitude":null,"longitude":null,"summary":"Laat je meenemen door de kracht van fotografie. Het Nederlands Fotomuseum bewaart het fotografische geheugen van Nederland en verbindt historische beelden met actuele verhalen. Tentoonstellingen geven ruimte aan uiteenlopende makers en manieren van kijken.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["fotografie","documentaire fotografie"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Rotterdam_bredehilledijk_pakhuis.jpg/1280px-Rotterdam_bredehilledijk_pakhuis.jpg","caption":"Nederlands Fotomuseum — Rotterdam bredehilledijk pakhuis","credit":"F.Eveleens","source_url":"https://commons.wikimedia.org/wiki/File:Rotterdam_bredehilledijk_pakhuis.jpg","license":"CC BY 3.0"}],"is_art_museum":true},{"id":"69812b36-6c10-5811-80ea-5afa65e5823e","inventory_key":"museum-nl:stedelijk-museum-alkmaar","name":"Stedelijk Museum Alkmaar","city":"Alkmaar","province":"Noord-Holland","street_address":"Canadaplein 1","postal_code":"1811 KE","country":"NL","website_url":"https://stedelijkmuseumalkmaar.nl/","latitude":52.6338,"longitude":4.743203,"summary":"Ontdek oude en moderne schilderkunst met Alkmaar als vertrekpunt. De museumcollectie en wisselende tentoonstellingen laten je kennismaken met kunstenaars, hun omgeving en nieuwe manieren van kijken naar stad en landschap.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["schilderkunst","oude kunst","moderne kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/79129-Stedelijk-Museum.jpg/1280px-79129-Stedelijk-Museum.jpg","caption":"Stedelijk Museum Alkmaar — 79129-Stedelijk-Museum","credit":"Peintre hollandais inconnu","source_url":"https://commons.wikimedia.org/wiki/File:79129-Stedelijk-Museum.jpg","license":"Public domain"}],"is_art_museum":true},{"id":"e979cace-a1ad-529f-ad13-218751d60b91","inventory_key":"museum-nl:textielmuseum","name":"TextielMuseum","city":"Tilburg","province":"Noord-Brabant","street_address":"Goirkestraat 96","postal_code":"5046 GN","country":"NL","website_url":"https://textielmuseum.nl/","latitude":51.570849,"longitude":5.079454,"summary":"Zie hoe draad verandert in kunst. In het TextielMuseum komen ontwerpen, mode en textielkunst samen met de praktijk van het maken. Historische technieken en hedendaagse experimenten laten je anders kijken naar stoffen om je heen.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["textielkunst","design","mode","toegepaste kunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Het_Textiel_museum_in_het_voorjaar_van_2020.jpg/1280px-Het_Textiel_museum_in_het_voorjaar_van_2020.jpg","caption":"TextielMuseum — Het Textiel museum in het voorjaar van 2020","credit":"GijsFrankenTK","source_url":"https://commons.wikimedia.org/wiki/File:Het_Textiel_museum_in_het_voorjaar_van_2020.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"7754eda6-25ee-5d9e-8359-15dd037f9d5c","inventory_key":"museum-nl:nieuwe-instituut","name":"Nieuwe Instituut","city":"Rotterdam","province":"Zuid-Holland","street_address":"Museumpark 25","postal_code":"3015 CB","country":"NL","website_url":"https://nieuweinstituut.nl/","latitude":51.914488,"longitude":4.470987,"summary":"Hoe geven ontwerpers vorm aan onze wereld? Het Nieuwe Instituut onderzoekt die vraag met tentoonstellingen over architectuur, design en digitale cultuur. Ontdek plannen, ideeën en experimenten die alledaagse omgevingen in een ander licht zetten.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["architectuur","design","digitale cultuur"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Gebouw_van_Het_NIeuwe_Instituut_in_Rotterdam.jpg/1280px-Gebouw_van_Het_NIeuwe_Instituut_in_Rotterdam.jpg","caption":"Nieuwe Instituut — Gebouw van Het NIeuwe Instituut in Rotterdam","credit":"Choinowski","source_url":"https://commons.wikimedia.org/wiki/File:Gebouw_van_Het_NIeuwe_Instituut_in_Rotterdam.jpg","license":"CC BY-SA 4.0"}],"is_art_museum":true},{"id":"a9c661b9-fa7f-5341-911b-30bb01e79778","inventory_key":"art-audit:51","name":"Slot Zeist","city":"Zeist","province":"Utrecht","street_address":"Zinzendorflaan 1","postal_code":"3703 CE","country":"NL","website_url":"https://www.slotzeist.nl/","latitude":null,"longitude":null,"summary":"Ontdek wisselende kunsttentoonstellingen in de culturele vleugel van Slot Zeist. Beeldende kunst krijgt hier een monumentale omgeving; ook buiten kan kunst een plek krijgen. Bekijk het actuele programma voor de lopende presentatie.","operating_status":"open","publication_status":"draft","verification_status":"unreviewed","tags":["kunsthal","hedendaagse kunst","beeldhouwkunst"],"photos":[{"url":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/Zeist_Het_Slot_A.jpg/1280px-Zeist_Het_Slot_A.jpg","caption":"Slot Zeist — Zeist Het Slot A","credit":"Wouter Hagens","source_url":"https://commons.wikimedia.org/wiki/File:Zeist_Het_Slot_A.jpg","license":"CC BY-SA 3.0"}],"is_art_museum":true}]'::jsonb)
 on conflict(id) do update set inventory_key=excluded.inventory_key,name=excluded.name,city=excluded.city,province=excluded.province,street_address=excluded.street_address,postal_code=excluded.postal_code,country=excluded.country,website_url=excluded.website_url,latitude=excluded.latitude,longitude=excluded.longitude,summary=excluded.summary,operating_status=excluded.operating_status,publication_status=excluded.publication_status,verification_status=excluded.verification_status,tags=excluded.tags,photos=excluded.photos,is_art_museum=excluded.is_art_museum
 where not m.is_art_museum and m.publication_status='draft'
 and not exists(select 1 from kunstkiezer_private.museum_changes c where c.museum_id=m.id and c.editor_id is not null)
 returning id
) insert into kk_art_changed select id from changed;
